37	/**
38	 * A collection of commonly used jclass objects that are used throughout
39	 * libhdfs. The jclasses are loaded immediately after the JVM is created (see
40	 * initCachedClasses). The array is indexed using CachedJavaClass.
41	 */
42	javaClassAndName cachedJavaClasses[NUM_CACHED_CLASSES];
