44	/**
45	 * Helper method that creates and sets a jclass object given a class name.
46	 * Returns a jthrowable on error, NULL otherwise.
47	 */
48	static jthrowable initCachedClass(JNIEnv *env, const char *className,
49	        jclass *cachedJclass) {
50	    assert(className != NULL && "Found a CachedJavaClass without a class "
51	                                "name");
52	    jthrowable jthr = NULL;
53	    jclass tempLocalClassRef;
54	    tempLocalClassRef = (*env)->FindClass(env, className);
55	    if (!tempLocalClassRef) {
56	        jthr = getPendingExceptionAndClear(env);
57	        goto done;
58	    }
59	    *cachedJclass = (jclass) (*env)->NewGlobalRef(env, tempLocalClassRef);
60	    if (!*cachedJclass) {
61	        jthr = getPendingExceptionAndClear(env);
62	        goto done;
63	    }
64	done:
65	    destroyLocalReference(env, tempLocalClassRef);
66	    return jthr;
67	}
