956	struct hdfsStreamBuilder *hdfsStreamBuilderAlloc(hdfsFS fs,
957	                                            const char *path, int flags)
958	{
959	    size_t path_len = strlen(path);
960	    struct hdfsStreamBuilder *bld;
961	
962	    // Check for overflow in path_len
963	    if (path_len > SIZE_MAX - sizeof(struct hdfsStreamBuilder)) {
964	        errno = EOVERFLOW;
965	        return NULL;
966	    }
967	    // sizeof(hdfsStreamBuilder->path) includes one byte for the string
968	    // terminator
969	    bld = malloc(sizeof(struct hdfsStreamBuilder) + path_len);
970	    if (!bld) {
971	        errno = ENOMEM;
972	        return NULL;
973	    }
974	    bld->fs = fs;
975	    bld->flags = flags;
976	    bld->bufferSize = 0;
977	    bld->replication = 0;
978	    bld->defaultBlockSize = 0;
979	    memcpy(bld->path, path, path_len);
980	    bld->path[path_len] = '\0';
981	    return bld;
982	}
