1022	/**
1023	 * Delegates to FsDataInputStream#hasCapability(String). Used to check if a
1024	 * given input stream supports certain methods, such as
1025	 * ByteBufferReadable#read(ByteBuffer).
1026	 *
1027	 * @param jFile the FsDataInputStream to call hasCapability on
1028	 * @param capability the name of the capability to query; for a full list of
1029	 *        possible values see StreamCapabilities
1030	 *
1031	 * @return true if the given jFile has the given capability, false otherwise
1032	 *
1033	 * @see org.apache.hadoop.fs.StreamCapabilities
1034	 */
1035	static int hdfsHasStreamCapability(jobject jFile,
1036	        const char *capability) {
1037	    int ret = 0;
1038	    jthrowable jthr = NULL;
1039	    jvalue jVal;
1040	    jstring jCapabilityString = NULL;
1041	
1042	    /* Get the JNIEnv* corresponding to current thread */
1043	    JNIEnv* env = getJNIEnv();
1044	    if (env == NULL) {
1045	        errno = EINTERNAL;
1046	        return 0;
1047	    }
1048	
1049	    jthr = newJavaStr(env, capability, &jCapabilityString);
1050	    if (jthr) {
1051	        ret = printExceptionAndFree(env, jthr, PRINT_EXC_ALL,
1052	                "hdfsHasStreamCapability(%s): newJavaStr", capability);
1053	        goto done;
1054	    }
1055	    jthr = invokeMethod(env, &jVal, INSTANCE, jFile,
1056	            JC_FS_DATA_INPUT_STREAM, "hasCapability", "(Ljava/lang/String;)Z",
1057	            jCapabilityString);
1058	    if (jthr) {
1059	        ret = printExceptionAndFree(env, jthr, PRINT_EXC_ALL,
1060	                "hdfsHasStreamCapability(%s): FSDataInputStream#hasCapability",
1061	                capability);
1062	        goto done;
1063	    }
1064	
1065	done:
1066	    destroyLocalReference(env, jthr);
1067	    destroyLocalReference(env, jCapabilityString);
1068	    if (ret) {
1069	        errno = ret;
1070	        return 0;
1071	    }
1072	    if (jVal.z == JNI_TRUE) {
1073	        return 1;
1074	    }
1075	    return 0;
1076	}
