1078	static hdfsFile hdfsOpenFileImpl(hdfsFS fs, const char *path, int flags,
1079	                  int32_t bufferSize, int16_t replication, int64_t blockSize)
1080	{
1081	    /*
1082	      JAVA EQUIVALENT:
1083	       File f = new File(path);
1084	       FSData{Input|Output}Stream f{is|os} = fs.create(f);
1085	       return f{is|os};
1086	    */
1087	    int accmode = flags & O_ACCMODE;
1088	    jstring jStrBufferSize = NULL, jStrReplication = NULL;
1089	    jobject jConfiguration = NULL, jPath = NULL, jFile = NULL;
1090	    jobject jFS = (jobject)fs;
1091	    jthrowable jthr;
1092	    jvalue jVal;
1093	    hdfsFile file = NULL;
1094	    int ret;
1095	    jint jBufferSize = bufferSize;
1096	    jshort jReplication = replication;
1097	
1098	    /* The hadoop java api/signature */
1099	    const char *method = NULL;
1100	    const char *signature = NULL;
1101	
1102	    /* Get the JNIEnv* corresponding to current thread */
1103	    JNIEnv* env = getJNIEnv();
1104	    if (env == NULL) {
1105	      errno = EINTERNAL;
1106	      return NULL;
1107	    }
1108	
1109	
1110	    if (accmode == O_RDONLY || accmode == O_WRONLY) {
1111		/* yay */
1112	    } else if (accmode == O_RDWR) {
1113	      fprintf(stderr, "ERROR: cannot open an hdfs file in O_RDWR mode\n");
1114	      errno = ENOTSUP;
1115	      return NULL;
1116	    } else {
1117	      fprintf(stderr, "ERROR: cannot open an hdfs file in mode 0x%x\n",
1118	              accmode);
1119	      errno = EINVAL;
1120	      return NULL;
1121	    }
1122	
1123	    if ((flags & O_CREAT) && (flags & O_EXCL)) {
1124	      fprintf(stderr,
1125	              "WARN: hdfs does not truly support O_CREATE && O_EXCL\n");
1126	    }
1127	
1128	    if (accmode == O_RDONLY) {
1129	        method = "open";
1130	        signature = JMETHOD2(JPARAM(HADOOP_PATH), "I", JPARAM(HADOOP_FSDISTRM));
1131	    } else if (flags & O_APPEND) {
1132	        method = "append";
1133	        signature = JMETHOD1(JPARAM(HADOOP_PATH), JPARAM(HADOOP_FSDOSTRM));
1134	    } else {
1135	        method = "create";
1136	        signature = JMETHOD2(JPARAM(HADOOP_PATH), "ZISJ", JPARAM(HADOOP_FSDOSTRM));
1137	    }
1138	
1139	    /* Create an object of org.apache.hadoop.fs.Path */
1140	    jthr = constructNewObjectOfPath(env, path, &jPath);
1141	    if (jthr) {
1142	        ret = printExceptionAndFree(env, jthr, PRINT_EXC_ALL,
1143	            "hdfsOpenFile(%s): constructNewObjectOfPath", path);
1144	        goto done;
1145	    }
1146	
1147	    /* Get the Configuration object from the FileSystem object */
1148	    jthr = invokeMethod(env, &jVal, INSTANCE, jFS, JC_FILE_SYSTEM,
1149	            "getConf", JMETHOD1("", JPARAM(HADOOP_CONF)));
1150	    if (jthr) {
1151	        ret = printExceptionAndFree(env, jthr, PRINT_EXC_ALL,
1152	            "hdfsOpenFile(%s): FileSystem#getConf", path);
1153	        goto done;
1154	    }
1155	    jConfiguration = jVal.l;
1156	
1157	    jStrBufferSize = (*env)->NewStringUTF(env, "io.file.buffer.size"); 
1158	    if (!jStrBufferSize) {
1159	        ret = printPendingExceptionAndFree(env, PRINT_EXC_ALL, "OOM");
1160	        goto done;
1161	    }
1162	    jStrReplication = (*env)->NewStringUTF(env, "dfs.replication");
1163	    if (!jStrReplication) {
1164	        ret = printPendingExceptionAndFree(env, PRINT_EXC_ALL, "OOM");
1165	        goto done;
1166	    }
1167	
1168	    if (!bufferSize) {
1169	        jthr = invokeMethod(env, &jVal, INSTANCE, jConfiguration,
1170	                JC_CONFIGURATION, "getInt",
1171	                "(Ljava/lang/String;I)I", jStrBufferSize, 4096);
1172	        if (jthr) {
1173	            ret = printExceptionAndFree(env, jthr, NOPRINT_EXC_FILE_NOT_FOUND |
1174	                NOPRINT_EXC_ACCESS_CONTROL | NOPRINT_EXC_UNRESOLVED_LINK,
1175	                "hdfsOpenFile(%s): Configuration#getInt(io.file.buffer.size)",
1176	                path);
1177	            goto done;
1178	        }
1179	        jBufferSize = jVal.i;
1180	    }
1181	
1182	    if ((accmode == O_WRONLY) && (flags & O_APPEND) == 0) {
1183	        if (!replication) {
1184	            jthr = invokeMethod(env, &jVal, INSTANCE, jConfiguration,
1185	                             JC_CONFIGURATION, "getInt",
1186	                             "(Ljava/lang/String;I)I", jStrReplication, 1);
1187	            if (jthr) {
1188	                ret = printExceptionAndFree(env, jthr, PRINT_EXC_ALL,
1189	                    "hdfsOpenFile(%s): Configuration#getInt(dfs.replication)",
1190	                    path);
1191	                goto done;
1192	            }
1193	            jReplication = (jshort)jVal.i;
1194	        }
1195	    }
1196	 
1197	    /* Create and return either the FSDataInputStream or
1198	       FSDataOutputStream references jobject jStream */
1199	
1200	    // READ?
1201	    if (accmode == O_RDONLY) {
1202	        jthr = invokeMethod(env, &jVal, INSTANCE, jFS, JC_FILE_SYSTEM,
1203	                method, signature, jPath, jBufferSize);
1204	    }  else if ((accmode == O_WRONLY) && (flags & O_APPEND)) {
1205	        // WRITE/APPEND?
1206	       jthr = invokeMethod(env, &jVal, INSTANCE, jFS, JC_FILE_SYSTEM,
1207	               method, signature, jPath);
1208	    } else {
1209	        // WRITE/CREATE
1210	        jboolean jOverWrite = 1;
1211	        jlong jBlockSize = blockSize;
1212	
1213	        if (jBlockSize == 0) {
1214	            jthr = getDefaultBlockSize(env, jFS, jPath, &jBlockSize);
1215	            if (jthr) {
1216	                ret = EIO;
1217	                goto done;
1218	            }
1219	        }
1220	        jthr = invokeMethod(env, &jVal, INSTANCE, jFS, JC_FILE_SYSTEM,
1221	                method, signature, jPath, jOverWrite, jBufferSize,
1222	                jReplication, jBlockSize);
1223	    }
1224	    if (jthr) {
1225	        ret = printExceptionAndFree(env, jthr, PRINT_EXC_ALL,
1226	            "hdfsOpenFile(%s): FileSystem#%s(%s)", path, method, signature);
1227	        goto done;
1228	    }
1229	    jFile = jVal.l;
1230	
1231	    file = calloc(1, sizeof(struct hdfsFile_internal));
1232	    if (!file) {
1233	        fprintf(stderr, "hdfsOpenFile(%s): OOM create hdfsFile\n", path);
1234	        ret = ENOMEM;
1235	        goto done;
1236	    }
1237	    file->file = (*env)->NewGlobalRef(env, jFile);
1238	    if (!file->file) {
1239	        ret = printPendingExceptionAndFree(env, PRINT_EXC_ALL,
1240	            "hdfsOpenFile(%s): NewGlobalRef", path); 
1241	        goto done;
1242	    }
1243	    file->type = (((flags & O_WRONLY) == 0) ? HDFS_STREAM_INPUT :
1244	        HDFS_STREAM_OUTPUT);
1245	    file->flags = 0;
1246	
1247	    if ((flags & O_WRONLY) == 0) {
1248	        // Check the StreamCapabilities of jFile to see if we can do direct
1249	        // reads
1250	        if (hdfsHasStreamCapability(jFile, "in:readbytebuffer")) {
1251	            file->flags |= HDFS_FILE_SUPPORTS_DIRECT_READ;
1252	        }
1253	
1254	        // Check the StreamCapabilities of jFile to see if we can do direct
1255	        // preads
1256	        if (hdfsHasStreamCapability(jFile, "in:preadbytebuffer")) {
1257	            file->flags |= HDFS_FILE_SUPPORTS_DIRECT_PREAD;
1258	        }
1259	    }
1260	    ret = 0;
1261	
1262	done:
1263	    destroyLocalReference(env, jStrBufferSize);
1264	    destroyLocalReference(env, jStrReplication);
1265	    destroyLocalReference(env, jConfiguration);
1266	    destroyLocalReference(env, jPath);
1267	    destroyLocalReference(env, jFile);
1268	    if (ret) {
1269	        if (file) {
1270	            if (file->file) {
1271	                (*env)->DeleteGlobalRef(env, file->file);
1272	            }
1273	            free(file);
1274	        }
1275	        errno = ret;
1276	        return NULL;
1277	    }
1278	    return file;
1279	}
