1281	hdfsFile hdfsStreamBuilderBuild(struct hdfsStreamBuilder *bld)
1282	{
1283	    hdfsFile file = hdfsOpenFileImpl(bld->fs, bld->path, bld->flags,
1284	                  bld->bufferSize, bld->replication, bld->defaultBlockSize);
1285	    int prevErrno = errno;
1286	    hdfsStreamBuilderFree(bld);
1287	    errno = prevErrno;
1288	    return file;
1289	}
